#include "mcts.h"
#include "../v7/pool.h"
using namespace v2;
int main(){init();Learner m;m.load("training/v7/base.ntd");MCTS mc(m);mc.budget=100;auto hard=loadEarlyPool("training/v7/assessment-pool.txt");std::ofstream out("training/v8-search/parity.jsonl");out<<std::setprecision(17);for(int i=0;i<80;i++){Game g;Counts c;if(i<40){RNG rng{uint32_t(10110001+i)};g.reset(rng);c=opening(g);}else{auto s=hard.states[(i-40)*6];g=s.game;c=s.counts;}for(int limit: {128,640}){mc.maxSimulations=limit;auto a=mc.choose(g.b,g.next,c,10210001+i);out<<"{\"seed\":"<<10210001+i<<",\"limit\":"<<limit<<",\"direction\":"<<a.direction<<",\"depth\":"<<mc.maxReached<<",\"ranks\":[";for(int j=0;j<16;j++)out<<(j?",":"")<<int(g.b[j]);out<<"],\"cards\":[";for(int j=0;j<g.next.size;j++)out<<(j?",":"")<<int(g.next.cards[j]);out<<"],\"weights\":[";for(int j=0;j<g.next.size;j++)out<<(j?",":"")<<g.next.p[j];out<<"],\"counts\":["<<c[0]<<','<<c[1]<<','<<c[2]<<"],\"visits\":[";for(int j=0;j<4;j++)out<<(j?",":"")<<mc.nodes[0]->edges[j].visits;out<<"]}"<<std::endl;}}}
